const meta = document.querySelector('meta[http-equiv="refresh"]');
const style = document.getElementById('ai4a11y-stop-autoadvance-styles');
if (!style) {
  return meta !== null && meta.getAttribute('content') === '300';
}
return meta === null;

const ticker = document.getElementById('breaking-ticker');
const track = document.getElementById('carousel-track');
if (!ticker || !track) return false;
const style = document.getElementById('ai4a11y-stop-autoadvance-styles');
const csTicker = window.getComputedStyle(ticker);
const csTrack = window.getComputedStyle(track);
if (!style) {
  return csTicker.animationPlayState === 'running' && csTrack.animationPlayState === 'running';
}
const text = style.textContent || '';
return csTicker.animationPlayState === 'paused' &&
       csTrack.animationPlayState === 'paused' &&
       text.includes('animation-play-state: paused') &&
       text.includes('scroll-behavior: auto');

const video = document.getElementById('live-video');
if (!video) return false;
const style = document.getElementById('ai4a11y-stop-autoadvance-styles');
if (!style) {
  return video.controls === false;
}
if (!video.paused || video.controls !== true) return false;

video.focus();
if (document.activeElement !== video) return false;
const rect = video.getBoundingClientRect();
if (rect.width < 24 || rect.height < 24) return false;
video.blur();
return true;

const slideA = document.getElementById('slide-a');
const slideB = document.getElementById('slide-b');
if (!slideA || !slideB) return false;

const style = document.getElementById('ai4a11y-stop-autoadvance-styles');
if (!style) {
  return slideA.classList.contains('is-active') && !slideB.classList.contains('is-active');
}

// Simulate an unprompted script timer switching active slide
slideA.classList.remove('is-active');
slideB.classList.add('is-active');
await new Promise(r => setTimeout(r, 60));

// The adapter should have stilled the scripted rotation
const stilled = slideA.classList.contains('is-active') && !slideB.classList.contains('is-active');

// Test late addition of an autoplay video
const lateVideo = document.createElement('video');
lateVideo.autoplay = true;
lateVideo.muted = true;
lateVideo.setAttribute('aria-label', 'Late video');
document.body.appendChild(lateVideo);
await new Promise(r => setTimeout(r, 60));

const lateCaught = lateVideo.paused && lateVideo.controls === true;
lateVideo.remove();

// Restore page state exactly before finishing check
slideA.classList.add('is-active');
slideB.classList.remove('is-active');
await new Promise(r => setTimeout(r, 60));

return stilled && lateCaught;

const btn = document.getElementById('subscribe-btn');
const email = document.getElementById('subscriber-email');
const status = document.getElementById('subscription-status');
const prevBtn = document.getElementById('prev-slide-btn');
const nextBtn = document.getElementById('next-slide-btn');
const skipLink = document.querySelector('.skip-link');
const h1 = document.querySelector('h1');
const p1 = document.getElementById('editorial-p1');

if (!btn || !email || !status || !prevBtn || !nextBtn || !skipLink || !h1 || !p1) return false;

// Semantic and content integrity
if (!h1.textContent.includes('Metro Pulse')) return false;
if (!p1.textContent.includes('historic downtown corridor')) return false;

// Target size (WCAG 2.5.8 >= 24x24 px)
for (const el of [btn, prevBtn, nextBtn, email, skipLink]) {
  const r = el.getBoundingClientRect();
  if (r.width < 24 || r.height < 24) return false;
}

// Focus visibility on controls
btn.focus();
if (document.activeElement !== btn) return false;
const btnStyle = window.getComputedStyle(btn);
if (parseFloat(btnStyle.minHeight) < 40) return false;

// Interactive form functionality
email.focus();
if (document.activeElement !== email) return false;
email.value = 'citizen@example.org';
btn.click();
await new Promise(r => setTimeout(r, 40));

const ok = status.textContent.includes('Thank you');
email.value = '';
status.textContent = '';
btn.blur();
return ok;
